insert into public.categories (slug, name, blurb, sort_order) values
('espresso', 'Espresso', 'The base of everything we do — pulled short, sweet and syrupy.', 1),
('americano', 'Americano', 'Long, clean and quietly aromatic.', 2),
('cappuccino', 'Cappuccino', 'Equal parts espresso, steam and silk.', 3),
('latte', 'Latte', 'Soft, milky and generous.', 4),
('mocha', 'Mocha', 'Real dark chocolate, never powder.', 5),
('cold-coffee', 'Cold Coffee', 'Slow-steeped and bright over ice.', 6),
('iced-drinks', 'Iced Drinks', 'Refreshers beyond the coffee bean.', 7),
('signature-drinks', 'Signature Drinks', 'Fourteen original recipes — the Aurevo palette.', 8),
('specialty-coffee', 'Specialty Coffee', 'Single-origin, brewed by hand.', 9),
('desserts', 'Desserts', 'Small, rich, finished with a flourish.', 10),
('bakery', 'Bakery', 'Laminated, baked and glazed each morning.', 11)
